const DATA = "";

function page() {
  const binary = atob(DATA);
  const bytes = Uint8Array.from(binary, (character) => character.charCodeAt(0));
  return new TextDecoder("utf-8").decode(bytes);
}

const HTML_HEADERS = {
  "Content-Type": "text/html; charset=UTF-8",
  "Cache-Control": "public, max-age=60",
  "Content-Security-Policy": "default-src 'self'; base-uri 'self'; object-src 'none'; frame-ancestors 'none'; form-action 'self'; script-src 'self' 'unsafe-inline' https://cdnjs.cloudflare.com; style-src 'self' 'unsafe-inline'; connect-src 'self' https://smart-home-api-v2.mykola-taran-88.workers.dev https://cdnjs.cloudflare.com; img-src 'self' data:; font-src 'self' data:",
  "X-Content-Type-Options": "nosniff",
  "Referrer-Policy": "strict-origin-when-cross-origin",
  "X-Frame-Options": "DENY",
  "Permissions-Policy": "camera=(), microphone=(), geolocation=()"
};

function isDashboardRoute(pathname) {
  const path = pathname.endsWith("/") && pathname !== "/" ? pathname.slice(0, -1) : pathname;
  if (["/", "/index.html", "/home", "/climate", "/energy", "/weather", "/timeline", "/admin", "/devices", "/about"].includes(path)) return true;
  const parts = path.split("/").filter(Boolean);
  return parts.length === 2 && parts[0] === "devices";
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (request.method !== "GET" && request.method !== "HEAD") {
      return new Response("Method Not Allowed", { status: 405, headers: { "Allow": "GET, HEAD", "Content-Type": "text/plain; charset=UTF-8" } });
    }
    if (!isDashboardRoute(url.pathname)) {
      return new Response("Not Found", { status: 404, headers: { "Content-Type": "text/plain; charset=UTF-8", "X-Content-Type-Options": "nosniff" } });
    }
    return new Response(request.method === "HEAD" ? null : page(), { status: 200, headers: HTML_HEADERS });
  }
};
